#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int ket = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 0 && ket == 0) ket = i;
    }
    printf("%d\n", ket);
    return 0;
}
